class Solution:
    def numDistinct(self, s, t):
        from functools import lru_cache

        @lru_cache(None)
        def dfs(i, j):
            if j == len(t):
                return 1
            if len(s) - i < len(t) - j:
                return 0
            total = dfs(i + 1, j)
            if s[i] == t[j]:
                total += dfs(i + 1, j + 1)
            return total

        return dfs(0, 0)

